package com.bank.optimize;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class EndpointOptimizationTest {

    ExecutorService ioPool = Executors.newFixedThreadPool(10);

    void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) {} }

        String fetchScore() { sleep(1000);
        return "SCORE:750"; }
        String fetchProperty() { sleep(1200);
        return "PROPERTY:5M"; }
        String fetchIncome() { sleep(800);
        return "INCOME:VERIFIED"; }

    // ═══ BEFORE: sequential ═══
    @Test
    void sequential_slow() {
        long start = System.currentTimeMillis();
        String score = fetchScore();        // 1000ms
        String property = fetchProperty();  // 1200ms
        String income = fetchIncome();      // 800ms
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isGreaterThanOrEqualTo(2900);  // ~3000ms sequential!
        System.out.println("Sequential: " + elapsed + "ms");
    }

    // ═══ AFTER: parallel with safeguards ═══
    @Test
    void parallel_fast() {
        long start = System.currentTimeMillis();

        CompletableFuture<String> scoreCF = CompletableFuture
            .supplyAsync(this::fetchScore, ioPool)
            .orTimeout(3, TimeUnit.SECONDS)
            .exceptionally(ex -> "SCORE:CACHED");

        CompletableFuture<String> propertyCF = CompletableFuture
            .supplyAsync(this::fetchProperty, ioPool)
            .orTimeout(3, TimeUnit.SECONDS)
            .exceptionally(ex -> "PROPERTY:UNKNOWN");

        CompletableFuture<String> incomeCF = CompletableFuture
            .supplyAsync(this::fetchIncome, ioPool)
            .orTimeout(3, TimeUnit.SECONDS)
            .exceptionally(ex -> "INCOME:PENDING");

        CompletableFuture.allOf(scoreCF, propertyCF, incomeCF).join();

        String result = scoreCF.join() + "|" + propertyCF.join() + "|" + incomeCF.join();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(result).contains("SCORE", "PROPERTY", "INCOME");
        assertThat(elapsed).isLessThan(2000);  // ~1200ms parallel! (slowest call)
        System.out.println("Parallel: " + elapsed + "ms");
    }

    // ═══ With timeout cap ═══
    @Test
    void parallel_withTimeoutCap() {
        long start = System.currentTimeMillis();

        CompletableFuture<String> slowCF = CompletableFuture
                .supplyAsync(() -> { sleep(10000);
                return "SLOW"; }, ioPool)
            .completeOnTimeout("CACHED", 2, TimeUnit.SECONDS);

        String result = slowCF.join();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(result).isEqualTo("CACHED");  // fallback!
        assertThat(elapsed).isLessThan(2500);     // capped at 2s!
    }
}
